#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines if they are open
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }

    // Close the GPIO chip if it's open
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    int value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line for GPIO 2
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 3
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_2);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line3, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1 and GPIO 3 to 0
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d value\n", GPIO_2);
            break;
        }
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d value\n", GPIO_3);
            break;
        }
        printf("GPIO %d: 1, GPIO %d: 0\n", GPIO_2, GPIO_3);
        sleep(2);

        // Set GPIO 2 to 0 and GPIO 3 to 1
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d value\n", GPIO_2);
            break;
        }
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d value\n", GPIO_3);
            break;
        }
        printf("GPIO %d: 0, GPIO %d: 1\n", GPIO_2, GPIO_3);
        sleep(2);
    }

    // Cleanup (in case the loop breaks due to an error)
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 1; // Indicate an error occurred
}

