#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int current_state = 0; // Start with LOW

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Main loop to toggle the GPIO state
    while (program_running) {
        gpio_status = gpioWrite(GPIO_PIN, current_state);

        if (gpio_status != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);

        // Toggle the state
        current_state = !current_state;

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

