// Function to read temperature from MLX90614
float read_temperature(int fd) {
    uint8_t data[2];
    int16_t raw_temp;
    float temp_celsius;

    // Write the register address to read from
    if (write(fd, &MLX90614_TOBJ1, 1) != 1) {
        perror("Failed to write to I2C device");
        return -273.15; // Return absolute zero on error
    }

    // Read two bytes from the device
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -273.15; // Return absolute zero on error
    }

    // Combine the two bytes into a 16-bit value
    raw_temp = (data[1] << 8) | data[0];

    // Convert the raw temperature to Celsius (see MLX90614 datasheet)
    temp_celsius = (float)raw_temp * 0.02 - 273.15;

    return temp_celsius;
}

int main() {
    float temperature;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("MLX90614 Temperature Reader\n");

    while (1) {
        temperature = read_temperature(i2c_fd);

        if (temperature > -273.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(5);
    }

    // The following lines will never be reached because of the infinite loop.
    close(i2c_fd);
    return 0;
}

