#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a register from the SI7021
int read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        perror("Failed to read register");
        return -1;
    }
    return result;
}

// Function to write a register to the SI7021
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Function to read temperature from the SI7021
int read_temperature(int fd) {
    if (write_register(fd, 0xF3, MEASURE_TEMP_HOLD) < 0) {
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    int msb = read_register(fd, 0xE3);
    int lsb = read_register(fd, 0xE4);

    if (msb < 0 || lsb < 0) {
        return -1;
    }

    uint16_t raw_temp = (msb << 8) | lsb;
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Basic validity check (example: reasonable range)
    if (temperature < -40.0 || temperature > 85.0) {
        fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
        return -1;
    }

    return (int)(temperature * 100); // Return as integer * 100 for precision
}

// Function to read humidity from the SI7021
int read_humidity(int fd) {
    if (write_register(fd, 0xF3, MEASURE_HUMID_HOLD) < 0) {
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    int msb = read_register(fd, 0xE3);
    int lsb = read_register(fd, 0xE4);

    if (msb < 0 || lsb < 0) {
        return -1;
    }

    uint16_t raw_humidity = (msb << 8) | lsb;
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    // Basic validity check (example: reasonable range)
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Invalid humidity reading: %.2f\n", humidity);
        return -1;
    }

    return (int)(humidity * 100); // Return as integer * 100 for precision
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("SI7021 sensor reader started. Press Ctrl+C to exit.\n");

    while (1) {
        int temp = read_temperature(i2c_fd);
        int humidity = read_humidity(i2c_fd);

        if (temp >= 0 && humidity >= 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", (float)temp / 100.0, (float)humidity / 100.0);
        } else {
            fprintf(stderr, "Failed to read temperature or humidity.\n");
        }

        sleep(5);
    }

    // This point will not be reached unless there's an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

