// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read from ADS1115
int16_t read_ads1115(int fd) {
    uint8_t config[3];
    uint8_t data[2];
    int16_t reading;

    // Construct configuration register value
    uint16_t config_value = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                            ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                            ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                            ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON |
                            ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Split the 16-bit config value into two bytes (MSB first)
    config[0] = (config_value >> 8) & 0xFF; // MSB
    config[1] = config_value & 0xFF;      // LSB

    // Write the configuration to the ADS1115
    if (write(fd, config, 2) != 2) {
        perror("Failed to write configuration to ADS1115");
        return -1; // Indicate error
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    if (write(fd, data, 1) != 1) {
        perror("Failed to write register address for reading");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read conversion data from ADS1115");
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    reading = (data[0] << 8) | data[1];

    return reading;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Perform 3 readings, one every 1 second
    for (int i = 0; i < 3; i++) {
        int16_t reading = read_ads1115(i2c_fd);
        if (reading == -1) {
            fprintf(stderr, "Error reading ADS1115, exiting.\n");
            close(i2c_fd);
            return 1;
        }
        printf("Reading %d: %d\n", i + 1, reading);
        sleep(1);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

