#define GPIO_23 23
#define GPIO_24 24

// Define the number of cycles
#define NUM_CYCLES 256

// Global variable to track the current cycle
volatile int current_cycle = 0;

// Function prototypes
void set_gpio_output(int gpio, int value);
void report_state(int gpio, int value);
void cleanup_handler(int signum);

// Signal handler for Ctrl+C
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Set all GPIOs to input mode (safer state)
    gpioSetMode(GPIO_8, PI_INPUT);
    gpioSetMode(GPIO_9, PI_INPUT);
    gpioSetMode(GPIO_10, PI_INPUT);
    gpioSetMode(GPIO_11, PI_INPUT);
    gpioSetMode(GPIO_23, PI_INPUT);
    gpioSetMode(GPIO_24, PI_INPUT);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set the output of a GPIO pin
void set_gpio_output(int gpio, int value) {
    gpioWrite(gpio, value);
}

// Function to report the state of a GPIO pin
void report_state(int gpio, int value) {
    printf("GPIO %d: %d\n", gpio, value);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_10, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Main loop
    while (current_cycle < NUM_CYCLES) {
        // Cycle through the GPIO pins and set their output
        set_gpio_output(GPIO_8, 1); report_state(GPIO_8, 1);
        set_gpio_output(GPIO_9, 0); report_state(GPIO_9, 0);
        set_gpio_output(GPIO_10, 1); report_state(GPIO_10, 1);
        set_gpio_output(GPIO_11, 0); report_state(GPIO_11, 0);
        set_gpio_output(GPIO_23, 1); report_state(GPIO_23, 1);
        set_gpio_output(GPIO_24, 0); report_state(GPIO_24, 0);

        current_cycle++;
        if (current_cycle >= NUM_CYCLES) break; // Exit loop after NUM_CYCLES

        set_gpio_output(GPIO_8, 0); report_state(GPIO_8, 0);
        set_gpio_output(GPIO_9, 1); report_state(GPIO_9, 1);
        set_gpio_output(GPIO_10, 0); report_state(GPIO_10, 0);
        set_gpio_output(GPIO_11, 1); report_state(GPIO_11, 1);
        set_gpio_output(GPIO_23, 0); report_state(GPIO_23, 0);
        set_gpio_output(GPIO_24, 1); report_state(GPIO_24, 1);

        current_cycle++;
        if (current_cycle >= NUM_CYCLES) break; // Exit loop after NUM_CYCLES

        // Small delay to avoid overwhelming the system
        gpioDelay(1000); // 1 millisecond
    }

    // Cleanup and exit
    cleanup_handler(0); // Call cleanup handler to reset GPIOs and terminate pigpio

    return 0;
}

