    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 distance measurement. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();
        report_distance(distance);
        gpioDelay(1000); // Wait 1 second
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

