#include <time.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_dht11(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_HIGH);
    gpioDelay(500);
    gpioWrite(gpio_pin, PI_LOW);
    gpioDelay(20000); //20ms
    gpioWrite(gpio_pin, PI_HIGH);
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP);
    gpioDelay(40);

    int timings[MAX_TIMINGS];
    int i = 0;
    unsigned int start = 0, end = 0;

    // Read timings
    for (i = 0; i < MAX_TIMINGS; i++) {
        start = gpioTick();
        while (gpioRead(gpio_pin) == laststate) {
            end = gpioTick();
            if (end - start > 200) {
                return -1; // Timeout
            }
        }
        laststate = gpioRead(gpio_pin);
        timings[i] = end - start;
    }

    // Decode data
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        if (timings[index] > 30) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2; // Checksum error
    }

    *humidity = (float)data[0] + (float)data[1] / 10.0;
    *temperature = (float)data[2] + (float)data[3] / 10.0;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    while (program_running) {
        result = read_dht11(DHT11_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT11 read failed with error code: %d\n", result);
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

