#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define NUM_CYCLES 3
#define CYCLE_DELAY_NS 100000000 // 0.1 seconds in nanoseconds

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int i;
    struct timespec ts;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0); // Initial value: 0 (LOW)
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d on %s is now in output mode.\n", GPIO_PIN, GPIO_CHIP);

    // Main loop: Toggle GPIO state for NUM_CYCLES
    for (i = 0; i < NUM_CYCLES && keep_running; ++i) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value to HIGH");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Delay for 0.1 seconds
        ts.tv_sec = 0;
        ts.tv_nsec = CYCLE_DELAY_NS;
        nanosleep(&ts, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value to LOW");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Delay for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d on %s released.\n", GPIO_PIN, GPIO_CHIP);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins to be used
const int pins[] = {2, 3, 4, 5, 6, 7, 8, 9, 17};
const int num_pins = sizeof(pins) / sizeof(pins[0]);

// Global variable to track the current state (0 or 1)
int current_state = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);

    // Set all pins to input mode (safer state)
    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(pins[i], PI_INPUT);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure each pin as an output
    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
    }

    // Main loop to toggle the GPIO pins
    while (1) {
        // Toggle the current state
        current_state = !current_state;

        // Set the state of each pin
        for (int i = 0; i < num_pins; i++) {
            gpioWrite(pins[i], current_state);
        }

        // Print the current state to standard output
        printf("State: %d\n", current_state);

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50 milliseconds = 50000 microseconds
    }

    // The program should never reach here, but include cleanup for safety
    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();
    return 0;
}

