#include <string.h>

#include <wiringPi.h>

int main ()
{
  int pin ;

  wiringPiSetupGpio () ;

  printf ( "Raspberry Pi blink\n") ;

  pin = 18 ;

  pinMode ( pin, OUTPUT ) ;

  for (;;)
  {
    digitalWrite ( pin, 1 ) ;
    printf ( "1") ;
    fflush ( stdout ) ;
    delay ( 500 ) ;

    digitalWrite ( pin, 0 ) ;
    printf ( "0") ;
    fflush ( stdout ) ;
    delay ( 500 ) ;
  }

  return 0 ;
}

