// Function to read a register from the OPT3001
int read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return buf[0];
}

// Function to write a register to the OPT3001
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the result register and convert to lux
float read_lux(int fd) {
    int raw_result = read_register(fd, RESULT_REG);
    if (raw_result < 0) {
        return -1.0f; // Indicate error
    }

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    int result = raw_result & 0x0FFF;

    // Calculate lux value
    float lux = 0.01 * pow(2, exponent) * result;
    return lux;
}

