        close(i2c_fd);
        return 1;
    }

    // Configure the OPT3001 (Continuous conversion mode, Range auto, Conversion time 100ms)
    uint16_t config_value = 0b1100000000000000; // Continuous mode, Auto range, 100ms conversion time
    if (write_register(i2c_fd, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        close(i2c_fd);
        return 1;
    }

    // Read the lux value
    float lux = read_lux(i2c_fd);
    if (lux < 0) {
        fprintf(stderr, "Failed to read lux value\n");
        close(i2c_fd);
        return 1;
    }

    // Print the lux value
    printf("Lux: %.2f\n", lux);

    // Close the I2C bus
    close(i2c_fd);

