    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop to toggle GPIO states
    for (i = 0; program_running; ++i) {
        // Toggle GPIO 17
        gpioWrite(GPIO_17, i % 2);
        printf("GPIO %d set to %d\n", GPIO_17, i % 2);

        // Toggle GPIO 18
        gpioWrite(GPIO_18, (i + 1) % 2);
        printf("GPIO %d set to %d\n", GPIO_18, (i + 1) % 2);

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

