#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your configuration
#define BAUD_RATE B9600
#define TIMEOUT_SEC 5
#define MAX_READ_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 0.1 seconds (10 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd) {
    char buffer[MAX_READ_SIZE];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);

    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    }

    buffer[bytes_read] = '\0'; // Null-terminate the string
    return (int)bytes_read;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART initialized. Reading data...\n");

    time_t start_time = time(NULL);
    int total_bytes_read = 0;

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd);
        if (bytes_read > 0) {
            printf("Received: %s", (char*)malloc(bytes_read + 1)); // Allocate memory for the string
            free((char*)malloc(bytes_read + 1)); // Free the allocated memory
            total_bytes_read += bytes_read;
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        if (time(NULL) - start_time >= TIMEOUT_SEC) {
            printf("Timeout reached. No data received for %d seconds.\n", TIMEOUT_SEC);
            break;
        }

        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    close(uart_fd);
    printf("UART port closed. Total bytes read: %d\n", total_bytes_read);

    return EXIT_SUCCESS;
}

