    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address 0x20, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Write GPIO state to I2C device
        if (i2cWriteByteData(i2c_handle, 0, gpio_state) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            break; // Exit loop on error
        }

