        gpio_state = (gpio_state == 0) ? 1 : 0;

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
