#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    int value17, value18;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 17
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 18
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Error getting GPIO line 18");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line17, "gpio17_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line18, "gpio18_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to 1
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 to 1");
            break;
        }
        value17 = 1;

        // Set GPIO 18 to 0
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("Error setting GPIO 18 to 0");
            break;
        }
        value18 = 0;

        // Print the state
        printf("GPIO 17: %d, GPIO 18: %d\n", value17, value18);

        // Wait 0.05 seconds
        usleep(50000); // 50 milliseconds

        // Set GPIO 17 to 0
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 to 0");
            break;
        }
        value17 = 0;

        // Set GPIO 18 to 1
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("Error setting GPIO 18 to 1");
            break;
        }
        value18 = 1;

        // Print the state
        printf("GPIO 17: %d, GPIO 18: %d\n", value17, value18);

        // Wait 0.05 seconds
        usleep(50000); // 50 milliseconds
    }

    // Cleanup (in case the loop breaks due to an error)
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Define PWM duty cycle
#define PWM_DUTY_CYCLE 500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(PWM_PIN_1, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Print the state of the GPIO pins
        printf("GPIO %d: PWM %d\n", PWM_PIN_1, PWM_DUTY_CYCLE);
        printf("GPIO %d: PWM %d\n", PWM_PIN_2, PWM_DUTY_CYCLE);
        printf("GPIO %d: PWM %d\n", PWM_PIN_3, PWM_DUTY_CYCLE);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define MAX_SENSORS 10
#define W1_DEVICES_PATH "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"

// Structure to hold sensor information
typedef struct {
    char id[20];
    int valid;
} sensor_t;

sensor_t sensors[MAX_SENSORS];
int num_sensors = 0;

volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to discover DS18B20 sensors
int discover_sensors() {
    DIR *dir;
    struct dirent *entry;
    int count = 0;

    dir = opendir(W1_DEVICES_PATH);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_PATH);
        return -1;
    }

    while ((entry = readdir(dir)) != NULL && count < MAX_SENSORS) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            strncpy(sensors[count].id, entry->d_name, sizeof(sensors[count].id) - 1);
            sensors[count].id[sizeof(sensors[count].id) - 1] = '\0'; // Ensure null termination
            sensors[count].valid = 0; // Initialize as invalid
            count++;
        }
    }

    closedir(dir);
    num_sensors = count;
    return 0;
}

// Function to read temperature from a sensor
float read_temperature(const char *sensor_id) {
    char path[100];
    char line[256];
    int fd;
    ssize_t bytes_read;
    int temp_valid = 0;
    float temperature = -999.0; // Default invalid temperature

    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_PATH, sensor_id, W1_SLAVE_FILE);

    fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -999.0;
    }

    // Read the file twice to ensure CRC check is valid
    lseek(fd, 0, SEEK_SET); // Rewind to the beginning of the file
    bytes_read = read(fd, line, sizeof(line) - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -999.0;
    }
    line[bytes_read] = '\0';

    lseek(fd, 0, SEEK_SET); // Rewind to the beginning of the file again
    bytes_read = read(fd, line, sizeof(line) - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -999.0;
    }
    line[bytes_read] = '\0';

    close(fd);

    // Check for CRC validation
    if (strstr(line, "YES") != NULL) {
        temp_valid = 1;
    }

    if (temp_valid) {
        char *temp_str = strstr(line, "t=");
        if (temp_str != NULL) {
            long temp_reading = strtol(temp_str + 2, NULL, 10);
            temperature = (float)temp_reading / 1000.0;
        }
    }

    return temperature;
}

int main() {
    int i;
    float temperature;
    time_t now;
    struct tm *timeinfo;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Discover sensors
    if (discover_sensors() != 0) {
        fprintf(stderr, "Failed to discover sensors. Exiting.\n");
        return 1;
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    printf("Found %d DS18B20 sensors.\n", num_sensors);

    // Main loop
    while (program_running) {
        for (i = 0; i < num_sensors; i++) {
            temperature = read_temperature(sensors[i].id);

            if (temperature != -999.0) {
                sensors[i].valid = 1; // Mark as valid if read successfully
                time(&now);
                timeinfo = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                printf("%s - Sensor %s: %.2f °C\n", timestamp, sensors[i].id, temperature);
            } else {
                sensors[i].valid = 0; // Mark as invalid
                fprintf(stderr, "Failed to read temperature from sensor %s\n", sensors[i].id);
            }
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define MEASUREMENT_DELAY_MS 50
#define READ_INTERVAL_SEC 60

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *bus);
int i2c_read_bytes(int fd, uint8_t addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t addr, uint8_t data);
int read_temperature(int fd, float *temperature);
int read_humidity(int fd, float *humidity);
void signal_handler(int sig);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// I2C initialization function
int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t addr, uint8_t *data, int len) {
    if (write(fd, &addr, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = addr;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Read temperature function
int read_temperature(int fd, float *temperature) {
    uint8_t data[3];
    int raw_temperature;

    if (i2c_write_byte(fd, HTU21D_ADDR, TEMP_MEASURE_CMD) < 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    if (i2c_read_bytes(fd, HTU21D_ADDR, data, 3) < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    raw_temperature = (data[0] << 8) | data[1];
    raw_temperature &= 0xFFFC; // Clear status bits

    *temperature = -46.85 + 175.72 * (raw_temperature / 65536.0);

    return 0;
}

// Read humidity function
int read_humidity(int fd, float *humidity) {
    uint8_t data[3];
    int raw_humidity;

    if (i2c_write_byte(fd, HTU21D_ADDR, HUMID_MEASURE_CMD) < 0) {
        fprintf(stderr, "Error writing humidity measurement command\n");
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    if (i2c_read_bytes(fd, HTU21D_ADDR, data, 3) < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    raw_humidity = (data[0] << 8) | data[1];
    raw_humidity &= 0xFFFC; // Clear status bits

    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        fprintf(stderr, "I2C bus closed.\n");
    }
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = READ_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    fprintf(stderr, "I2C initialized successfully.\n");

    // Main loop
    while (!terminate) {
        float temperature, humidity;

        if (read_temperature(i2c_fd, &temperature) == 0 &&
            read_humidity(i2c_fd, &humidity) == 0) {

            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal.\n");
            } else {
                perror("nanosleep");
                fprintf(stderr, "Sleep failed. Exiting.\n");
                cleanup();
                return 1;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

