static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    int ret;
    int value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d on %s is now in output mode.\n", GPIO_PIN, GPIO_CHIP);

    // Toggle GPIO output
    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value to 1");
            break;
        }
        value = 1;
        printf("GPIO %d set to %d\n", GPIO_PIN, value);
        usleep(50000); // 50ms

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value to 0");
            break;
        }
        value = 0;
        printf("GPIO %d set to %d\n", GPIO_PIN, value);
        usleep(50000); // 50ms
    }

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

