// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    // Set data format: +/- 2g range, full resolution
    if (i2c_smbus_write_byte_data(fd, DATA_FORMAT, 0x08) < 0) {
        perror("Error writing to DATA_FORMAT register");
        return -1;
    }

    // Enable measurement mode
    if (i2c_smbus_write_byte_data(fd, POWER_CTL, 0x08) < 0) {
        perror("Error writing to POWER_CTL register");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (read(fd, data, 6) != 6) {
        perror("Error reading data from ADXL345");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (adxl345_read_data(i2c_fd, &x, &y, &z) == 0) {
            // Print the data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        // Delay for 0.1 seconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&delay, NULL);
    }

    // Close I2C device (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

