// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Control register values
#define TCS34725_CONTROL_AGAIN_60X 0x03

int i2c_fd = -1; // I2C file descriptor

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the TCS34725 sensor
int init_tcs34725(int fd) {
    // Enable power and ALS
    if (i2c_smbus_write_byte_data(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time (ATIME).  2.4ms * 256 = 614.4ms
    if (i2c_smbus_write_byte_data(fd, TCS34725_ATIME, 0xEB) < 0) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set gain (AGAIN).  60x gain
    if (i2c_smbus_write_byte_data(fd, TCS34725_CONTROL, TCS34725_CONTROL_AGAIN_60X) < 0) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// Function to read data from the TCS34725 sensor
int read_tcs34725(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    *clear = i2c_smbus_read_word_data(fd, TCS34725_CDATA);
    *red   = i2c_smbus_read_word_data(fd, TCS34725_RDATA);
    *green = i2c_smbus_read_word_data(fd, TCS34725_GDATA);
    *blue  = i2c_smbus_read_word_data(fd, TCS34725_BDATA);

    if (*clear == -1 || *red == -1 || *green == -1 || *blue == -1) {
        perror("Error reading data from sensor");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (1) {
        uint16_t clear, red, green, blue;

        // Read data from the sensor
        if (read_tcs34725(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Print the data
            printf("C: %5u, R: %5u, G: %5u, B: %5u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read data from TCS34725 sensor.\n");
        }

        // Wait for 0.2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 0.2 seconds
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

