// SSD1306 I2C address
#define SSD1306_I2C_ADDR 0x3C

// SSD1306 display dimensions
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// I2C file descriptor
int i2c_fd;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to write a command to the SSD1306
void ssd1306_command(unsigned char command) {
    unsigned char buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command to SSD1306");
    }
}

// Function to write data to the SSD1306
void ssd1306_data(unsigned char data) {
    unsigned char buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write data to SSD1306");
    }
}

// Function to initialize the SSD1306
void ssd1306_init() {
    ssd1306_command(0xAE); // Display off
    ssd1306_command(0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_command(0x80); // --ratio
    ssd1306_command(0xA8); // Set multiplex ratio
    ssd1306_command(0x3F); // --ratio
    ssd1306_command(0xD3); // Set display offset
    ssd1306_command(0x00); // --offset
    ssd1306_command(0x40); // Set start line address
    ssd1306_command(0x8D); // Charge pump setting
    ssd1306_command(0x14); // --enable
    ssd1306_command(0x20); // Set memory addressing mode
    ssd1306_command(0x00); // --horizontal addressing mode
    ssd1306_command(0xA1); // Set segment re-map
    ssd1306_command(0xC8); // Set COM output scan direction
    ssd1306_command(0xDA); // Set COM pins hardware configuration
    ssd1306_command(0x12); // --configuration
    ssd1306_command(0x81); // Set contrast control
    ssd1306_command(0xCF); // --contrast
    ssd1306_command(0xD9); // Set pre-charge period
    ssd1306_command(0xF1); // --period
    ssd1306_command(0xDB); // Set VCOM deselect level
    ssd1306_command(0x40); // --level
    ssd1306_command(0xA4); // Display all points off
    ssd1306_command(0xA6); // Set normal display
    ssd1306_command(0xAF); // Display on
}

// Function to clear the display
void ssd1306_clear() {
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        ssd1306_data(0x00);
    }
}

// Function to display a string at a specific position
void ssd1306_display_string(int x, int y, const char *str) {
    // Set column and page address
    ssd1306_command(0xB0 + y);       // Set page address
    ssd1306_command(0x00 + (x & 0x0F)); // Set lower column address
    ssd1306_command(0x10 + ((x >> 4) & 0x0F)); // Set higher column address

    // Write the string data
    for (int i = 0; str[i] != '\0'; i++) {
        // Simple font (5x8) - replace with your font data
        // This is a placeholder, you'll need a real font
        for (int j = 0; j < 5; j++) {
            ssd1306_data(0xFF); // Placeholder: replace with actual font data
        }
        ssd1306_data(0x00); // Space between characters
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize SSD1306
    ssd1306_init();

    // Main loop
    while (!terminate) {
        // Get current time
        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t nowtime = tv.tv_sec;
        struct tm *nowtm = localtime(&nowtime);
        char tmbuf[64], buf[64];
        strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
        snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

        // Display the time
        ssd1306_clear();
        ssd1306_display_string(0, 0, buf);

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and exit
    ssd1306_clear();
    close(i2c_fd);
    return 0;
}

