    }

    // Main loop
    while (program_running) {
        // Iterate through GPIO pins and set their states
        for (i = 0; i < num_pins; i++) {
            // Set GPIO high
            result = gpioWrite(gpio_pins[i], 1);
            if (result != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pins[i], result);
            } else {
