// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 24

// Define timeout in microseconds
#define TIMEOUT 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT) {
        timeout_counter++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout_counter >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT) {
        timeout_counter++;
        gpioDelay(1);
    }

    if (timeout_counter >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate pulse width
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_width * 0.000001) * 34300 / 2
    float distance = (float)diff_tick * 0.000001 * 34300 / 2.0;

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }

        gpioDelay(200); // 0.2 second delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

