#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV format
#define CAPTURE_INTERVAL_SEC 0.05

static int fd = -1; // File descriptor for the video device
static void *buffer = NULL; // Memory-mapped buffer for the image
static FILE *image_file = NULL; // File pointer for the output image file
static volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting...\n");
        stop_flag = 1;
    }
}

// Function to initialize the video device
int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return 0;
}

// Function to start capturing
int start_capturing() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const char *filename) {
    image_file = fopen(filename, "wb");
    if (image_file == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, IMAGE_SIZE, image_file);
    if (bytes_written != IMAGE_SIZE) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(image_file);
        return -1;
    }

    fclose(image_file);
    return 0;
}

// Function to stop capturing
int stop_capturing() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to uninitialize the device
int uninit_device() {
    if (buffer != NULL && buffer != MAP_FAILED) {
        if (munmap(buffer, IMAGE_SIZE) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
        buffer = NULL;
    }

    if (fd != -1) {
        close(fd);
        fd = -1;
    }
    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = CAPTURE_INTERVAL_SEC * 1000000000; // Convert seconds to nanoseconds

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize the device
    if (init_device() < 0) {
        fprintf(stderr, "Device initialization failed\n");
        return 1;
    }

    // Start capturing
    if (start_capturing() < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        uninit_device();
        return 1;
    }

    // Capture loop
    while (!stop_flag) {
        // Capture image
        if (capture_image() < 0) {
            fprintf(stderr, "Failed to capture image\n");
            break;
        }

        // Save image
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%ld.yuyv", time(NULL));
        if (save_image(filename) < 0) {
            fprintf(stderr, "Failed to save image\n");
            break;
        }

        // Sleep for the specified interval
        if (nanosleep(&sleep_time, NULL) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal\n");
                break;
            } else {
                fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Stop capturing
    if (stop_capturing() < 0) {
        fprintf(stderr, "Failed to stop capturing\n");
    }

    // Uninitialize the device
    if (uninit_device() < 0) {
        fprintf(stderr, "Failed to uninitialize device\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
