// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the BME280
int read_bme280_register(int fd, uint8_t reg_addr) {
    int result = i2c_smbus_read_byte_data(fd, reg_addr);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to the BME280
int write_bme280_register(int fd, uint8_t reg_addr, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg_addr, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature, pressure, and humidity from the BME280
int read_bme280_data(int fd, float *temperature, float *pressure, float *humidity) {
    // Set the BME280 to forced mode
    if (write_bme280_register(fd, BME280_REG_CTRL_MEAS, 0x25) < 0) { // Temperature and pressure oversampling x1, forced mode
        return -1;
    }
    if (write_bme280_register(fd, BME280_REG_CTRL_HUM, 0x01) < 0) { // Humidity oversampling x1
        return -1;
    }
    if (write_bme280_register(fd, BME280_REG_CONFIG, 0x00) < 0) { // Normal mode, t_sb = 0.5ms, filter off
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    usleep(10000); // 10ms

    // Read the raw data
    int32_t raw_temperature = 0;
    int32_t raw_pressure = 0;
    int32_t raw_humidity = 0;

    raw_pressure = (read_bme280_register(fd, BME280_REG_PRESSURE_MSB) << 12) | (read_bme280_register(fd, BME280_REG_PRESSURE_MSB + 1) << 4) | (read_bme280_register(fd, BME280_REG_PRESSURE_MSB + 2) >> 4);
    raw_temperature = (read_bme280_register(fd, BME280_REG_TEMP_MSB) << 12) | (read_bme280_register(fd, BME280_REG_TEMP_MSB + 1) << 4) | (read_bme280_register(fd, BME280_REG_TEMP_MSB + 2) >> 4);
    raw_humidity = (read_bme280_register(fd, BME280_REG_HUMIDITY_MSB) << 8) | read_bme280_register(fd, BME280_REG_HUMIDITY_MSB + 1);

    // Dummy conversion (replace with actual BME280 conversion formulas)
    *temperature = (float)raw_temperature / 100.0;
    *pressure = (float)raw_pressure / 100.0;
    *humidity = (float)raw_humidity / 100.0;

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
