// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060  // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t buf[2];
    int16_t value;

    // Write the register address to read from
    if (write(fd, buf, 0) != 0) {
        perror("Failed to write register address");
        return -1;
    }

    // Read two bytes from the register
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    value = (buf[0] << 8) | buf[1];

    return value;
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint16_t value) {
    uint8_t buf[3];

    // Set the register address to write to
    buf[0] = ADS1115_REG_CONFIG;

    // Set the value to write
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    // Write the register address and value
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure the ADS1115 for single-ended AIN0, +/-4.096V, single-shot mode, 128 SPS
        uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                          ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                          ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_QUE_DISABLE;

        // Write the configuration to the ADS1115
        if (write_ads1115(i2c_fd, config) < 0) {
            fprintf(stderr, "Failed to write configuration to ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for the conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        int16_t raw_value = read_ads1115(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read value from ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Print the raw value
        printf("Raw Value: %d\n", raw_value);

        // Wait 0.2 seconds
        usleep(200000); // 200ms
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

