    while (program_running) {
        // Set the GPIO pin to the current state
        result = gpioWrite(GPIO_PIN, current_state);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_PIN, result);
            gpioTerminate();
            return 1;
        }

        // Print the current state
        printf("GPIO %d is now %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");

        // Toggle the state
