// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 500000      // 0.5 seconds

// Global variables
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
double measure_distance();
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate pulse width
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2

    // Validate distance
    if (distance < 0.0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        return -1.0; // Indicate invalid reading
    }

    return distance;
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(ECHO_PIN, 0);
    gpioSetMode(TRIGGER_PIN, PI_INPUT); // Set to input to avoid spurious signals
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to measure distance\n");
        }

        gpioDelay(100); // 0.1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

