// Configuration
#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CHANNEL_0 0x4000
#define ADS1115_GAIN_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0060
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_CLIENT_ID "rpi_ads1115_sensor"
#define MQTT_TOPIC "sensor/readings"
#define NUM_READINGS 10

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static MQTTClient client;
static char clientID[50];

// Function prototypes
int ads1115_init(int address);
int16_t ads1115_read_adc(int fd, int channel);
double ads1115_convert_to_voltage(int16_t raw_value);
int mqtt_connect(const char *client_id, const char *broker_address);
int mqtt_publish(MQTTClient client, const char *topic, const char *payload);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keepRunning = 0;
}

// Initialize the ADS1115
int ads1115_init(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Configure the ADS1115 for single-ended channel 0, +/-4.096V, 128 SPS
    int config = ADS1115_CHANNEL_0 | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS;
    wiringPiI2CWriteReg16(fd, ADS1115_CONFIG_REG, config);
    return fd;
}

// Read ADC value from the ADS1115
int16_t ads1115_read_adc(int fd, int channel) {
    // Start a single conversion
    int config = 0;
    switch (channel) {
        case 0: config = ADS1115_CHANNEL_0 | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS; break;
        case 1: config = ADS1115_CHANNEL_1 | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS; break;
        case 2: config = ADS1115_CHANNEL_2 | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS; break;
        case 3: config = ADS1115_CHANNEL_3 | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS; break;
        default: fprintf(stderr, "Invalid channel number.\n"); return -1;
    }
    wiringPiI2CWriteReg16(fd, ADS1115_CONFIG_REG, config);

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    delay(10);

    // Read the conversion result
    int16_t raw_value = wiringPiI2CReadReg16(fd, ADS1115_CONVERSION_REG);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
        return -1;
    }

    // The ADS1115 returns the MSB first, so we need to swap bytes
    return (raw_value >> 8) | (raw_value << 8);
}

// Convert raw ADC value to voltage
double ads1115_convert_to_voltage(int16_t raw_value) {
    // ADS1115 is a 16-bit ADC, but only 15 bits are used for the conversion.
    // The sign bit is the 16th bit.
    // The full-scale range is +/- 4.096V, so the LSB is 4.096 / 2^15 = 0.000125 V
    double voltage = (double)raw_value * 0.000125;
    return voltage;
}

// Connect to the MQTT broker
int mqtt_connect(const char *client_id, const char *broker_address) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    MQTTClient_create(&client, broker_address, client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }
    return 0;
}

// Publish a message to the MQTT broker
int mqtt_publish(MQTTClient client, const char *topic, const char *payload) {
    int rc;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    // Wait for delivery to complete
    rc = MQTTClient_waitForCompletion(client, token, 1000); // Wait for 1 second
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for message delivery, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the ADS1115
    i2c_fd = ads1115_init(ADS1115_ADDRESS);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize MQTT
    if (mqtt_connect(MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS) != 0) {
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    for (int i = 0; i < NUM_READINGS && keepRunning; ++i) {
        // Read ADC value
        int16_t raw_value = ads1115_read_adc(i2c_fd, 0); // Read from channel 0
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC, skipping.\n");
            continue;
        }

        // Convert to voltage
        double voltage = ads1115_convert_to_voltage(raw_value);

        // Create JSON payload
        char payload[100];
        snprintf(payload, sizeof(payload), "{\"voltage\": %.3f}", voltage);

        // Publish to MQTT
        if (mqtt_publish(client, MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error publishing MQTT message, skipping.\n");
        }

        printf("Published: %s\n", payload);

        // Wait before next reading
        delay(1000); // 1 second
    }

    // Clean up
    printf("Cleaning up...\n");
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    close(i2c_fd);

    return 0;
}

