        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer and gyroscope values
        int16_t accel_x = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H + 4);
        int16_t gyro_x = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H + 4);

        // Check for errors during read
        if (accel_x == -1 || accel_y == -1 || accel_z == -1 || gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
            fprintf(stderr, "Error reading MPU6050 values. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Print the values
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Sleep for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

