// Configuration
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_PIN 4 // Example GPIO pin for sensor
#define PUBLISH_INTERVAL_MS 1000 // Publish every 1 second

// Global variables
volatile sig_atomic_t terminate = 0;
MQTTClient client;
int gpio_initialized = 0;

// Structure to hold sensor data
typedef struct {
    int sensor_value;
    char timestamp[30];
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpio_initialized = 1;
    gpioSetMode(SENSOR_PIN, PI_INPUT); // Set sensor pin as input
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    // Simulate reading sensor data (replace with actual sensor reading logic)
    data->sensor_value = gpioRead(SENSOR_PIN); // Example: Read digital value from GPIO

    // Get current timestamp
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm_info = localtime(&tv.tv_sec);
    strftime(data->timestamp, sizeof(data->timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(data->timestamp + strlen(data->timestamp), sizeof(data->timestamp) - strlen(data->timestamp), ".%03d", (int)(tv.tv_usec / 1000));

    return 0;
}

// Function to publish sensor data to MQTT broker
int publish_sensor_data(const sensor_data_t *data) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[100];

    // Format the payload
    snprintf(payload, sizeof(payload), "{\"sensor_value\": %d, \"timestamp\": \"%s\"}", data->sensor_value, data->timestamp);

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1; // Quality of Service level 1
    pubmsg.retained = 0;

    MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    printf("Published: %s\n", payload);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (gpio_initialized) {
        gpioTerminate();
    }
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize MQTT client
    int rc;
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        cleanup();
        return 1;
    }

    printf("Connected to MQTT broker\n");

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Publish sensor data
            publish_sensor_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next publish interval
        gpioDelay(PUBLISH_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
