#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILENAME "image.jpg"

static int fd = -1; // File descriptor for the video device
static void *buffer = NULL; // Memory buffer for the image data
static size_t buffer_size = 0; // Size of the memory buffer

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting...\n");
        if (buffer != NULL) {
            munmap(buffer, buffer_size);
        }
        if (fd != -1) {
            close(fd);
        }
        exit(0);
    }
}

// Function to capture an image
int capture_image() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0; // Assuming only one buffer is used

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    // Save the image to a file
    FILE *fp = fopen(IMAGE_FILENAME, "wb");
    if (fp == NULL) {
        perror("Failed to open image file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) == -1) {
        perror("VIDIOC_STREAMOFF failed");
        return -1;
    }

    return 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Failed to open video device");
        return 1;
    }

    // Check if the device is a V4L2 device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS failed");
        close(fd);
        return 1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF failed");
        close(fd);
        return 1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return 1;
    }

    // Queue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        perror("VIDIOC_STREAMON failed");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Capture images in a loop
    while (1) {
        if (capture_image() != 0) {
            fprintf(stderr, "Failed to capture image\n");
        }
        sleep(1);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    munmap(buffer, buffer_size);
    close(fd);

    return 0;
}

