        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec) > DHT22_RESPONSE_SIGNAL) {
            fprintf(stderr, "DHT22 response timeout\n");
            gpiod_line_release(line);
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    if ((end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec) < DHT22_RESPONSE_SIGNAL) {
        fprintf(stderr, "DHT22 response signal too short\n");
        gpiod_line_release(line);
        return -1;
    }

