// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel to read
#define MQTT_BROKER "tcp://localhost:1883" // Replace with your broker address
#define MQTT_CLIENT_ID "rpi_mcp3008_sensor"
#define MQTT_TOPIC "home/sensors/mcp3008"
#define MQTT_QOS 1
#define MQTT_RETAIN 0

// Global variables
int spi_handle;
MQTTClient client;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    char broker_address[100];
    char client_id[50];
    char topic[100];
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
} config_t;

// Function prototypes
int read_mcp3008(int channel);
int publish_sensor_reading(int reading);
void signal_handler(int signal);
int mqtt_connect();
void mqtt_disconnect();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to publish sensor reading to MQTT broker
int publish_sensor_reading(int reading) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", reading);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = MQTT_RETAIN;

    MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    MQTTClient_waitForCompletion(client, token, 1000); // Wait for 1 second

    printf("Published: %s to topic: %s\n", payload, MQTT_TOPIC);
    return 0;
}

// Function to connect to MQTT broker
int mqtt_connect() {
    int rc;

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }
    printf("Connected to MQTT broker\n");
    return 0;
}

// Function to disconnect from MQTT broker
void mqtt_disconnect() {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Disconnected from MQTT broker\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT client
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Connect to MQTT broker
    if (mqtt_connect() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor value
        int sensor_value = read_mcp3008(MCP3008_CHANNEL);
        if (sensor_value >= 0) {
            // Publish sensor reading
            publish_sensor_reading(sensor_value);
        } else {
            fprintf(stderr, "Failed to read sensor value\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Disconnect from MQTT broker
    mqtt_disconnect();

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

