#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17

/* Global variable to track program state for signal handling */
volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    int current_state = 0; // 0: LOW, 1: HIGH

    /* Register the signal handler for SIGINT */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    /* Initialize the pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 17 as an output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Main loop to toggle the GPIO state */
    while (program_running) {
        /* Set the GPIO state */
        gpioWrite(GPIO_PIN, current_state);

        /* Print the current state */
        printf("GPIO %d is now %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");

        /* Toggle the state */
        current_state = !current_state;

        /* Wait for 5 seconds */
        sleep(5);
    }

    /* Clean up and terminate the pigpio library */
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

// Define the PCF8574 pins connected to the 7-segment display segments
#define SEG_A 0
#define SEG_B 1
#define SEG_C 2
#define SEG_D 3
#define SEG_E 4
#define SEG_F 5
#define SEG_G 6
#define SEG_DP 7

// Define the PCF8574 pins connected to the 7-segment display digit select lines
#define DIGIT_1 8
#define DIGIT_2 9
#define DIGIT_3 10
#define DIGIT_4 11

// Define the segment patterns for each digit (0-9)
const uint8_t segment_patterns[] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F  // 9
};

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to write a byte to the PCF8574
int write_byte(int fd, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to display a digit on the 7-segment display
void display_digit(int digit, int value) {
    if (digit < 0 || digit > 3 || value < 0 || value > 9) {
        fprintf(stderr, "Invalid digit or value: digit=%d, value=%d\n", digit, value);
        return;
    }

    // Clear all digit select lines
    uint8_t digit_select = 0x00;
    digit_select |= (1 << DIGIT_1);
    digit_select |= (1 << DIGIT_2);
    digit_select |= (1 << DIGIT_3);
    digit_select |= (1 << DIGIT_4);

    // Set the segment pattern for the digit
    uint8_t segment_pattern = segment_patterns[value];

    // Combine the digit select and segment pattern
    uint8_t data = digit_select | segment_pattern;

    // Write the data to the PCF8574
    if (write_byte(i2c_fd, data) < 0) {
        fprintf(stderr, "Error writing to PCF8574\n");
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Display the digits 1234
        display_digit(0, 1);
        usleep(1000); // Small delay to allow the digit to be displayed
        display_digit(1, 2);
        usleep(1000);
        display_digit(2, 3);
        usleep(1000);
        display_digit(3, 4);
        usleep(1000);

        // Wait for 0.5 seconds
        usleep(500000);
    }

    return 0;
}

