#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = 0; // 0: LOW, 1: HIGH

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Set the GPIO pin to the current state
        gpioWrite(GPIO_PIN, current_state);

        // Print the current state to standard output
        printf("GPIO %d is now %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");

        // Toggle the state
        current_state = !current_state;

        // Wait for 2 seconds
        sleep(2);
    }

    // Clean up and release GPIO resources before exiting
    gpioWrite(GPIO_PIN, 0); // Set to LOW before exiting
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input mode
    gpioTerminate();

    printf("GPIO %d control stopped.\n", GPIO_PIN);

    return 0;
}

