// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate pulse width
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (diff_tick * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main() {
