        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

