        start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        // Falling edge: record end time
        end_tick = tick;
        echo_received = 0; // Reset the flag

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance, convert us to s

