// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H 0x43

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(fd, MPU6050_REG_PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    // Read accelerometer data
    int16_t raw_accel_x = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_XOUT_H);
    if (raw_accel_x < 0) {
        perror("Error reading accelerometer X data");
        return -1;
    }
    int16_t raw_accel_y = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_XOUT_H + 2);
    if (raw_accel_y < 0) {
        perror("Error reading accelerometer Y data");
        return -1;
    }
    int16_t raw_accel_z = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_XOUT_H + 4);
    if (raw_accel_z < 0) {
        perror("Error reading accelerometer Z data");
        return -1;
    }

    // Read gyroscope data
    int16_t raw_gyro_x = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_XOUT_H);
    if (raw_gyro_x < 0) {
        perror("Error reading gyroscope X data");
        return -1;
    }
    int16_t raw_gyro_y = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_XOUT_H + 2);
    if (raw_gyro_y < 0) {
        perror("Error reading gyroscope Y data");
        return -1;
    }
    int16_t raw_gyro_z = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_XOUT_H + 4);
    if (raw_gyro_z < 0) {
        perror("Error reading gyroscope Z data");
        return -1;
    }

    // Store the data
    *accel_x = raw_accel_x;
    *accel_y = raw_accel_y;
    *accel_z = raw_accel_z;
    *gyro_x = raw_gyro_x;
    *gyro_y = raw_gyro_y;
    *gyro_z = raw_gyro_z;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (program_running) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read data from MPU6050
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data.\n");
        }

        // Delay for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device
    close(i2c_fd);
    printf("I2C device closed.\n");

    return 0;
}

