// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t write_buf[2];
    uint8_t read_buf[6];
    int ret;

    // Send measurement command
    write_buf[0] = (SHT31_MEASURE_CMD >> 8) & 0xFF;
    write_buf[1] = SHT31_MEASURE_CMD & 0xFF;

    ret = write(fd, write_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (typical conversion time is 10ms, but we wait longer)
    usleep(20000); // 20ms

    // Read 6 bytes of data (Temp MSB, Temp LSB, Temp CRC, Hum MSB, Hum LSB, Hum CRC)
    ret = read(fd, read_buf, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // CRC check for temperature data
    uint8_t temp_data[2] = {read_buf[0], read_buf[1]};
    uint8_t temp_crc = read_buf[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // CRC check for humidity data
    uint8_t hum_data[2] = {read_buf[3], read_buf[4]};
    uint8_t hum_crc = read_buf[5];
    if (crc8(hum_data, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temp_raw = (read_buf[0] << 8) | read_buf[1];
    int hum_raw = (read_buf[3] << 8) | read_buf[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        ret = read_sht31(i2c_fd, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT31 data.\n");
        }

        sleep(5);
    }

    // This point should not be reached due to the signal handler
    close(i2c_fd);
    return 0;
}

