#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int main() {
    int i, result;

    // Register the signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 and GPIO 3 as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Main loop to toggle GPIO states
    for (i = 0; program_running; ++i) {
        // Toggle GPIO 2
        gpioWrite(GPIO_2, i % 2);
        printf("GPIO %d set to %d\n", GPIO_2, i % 2);

        // Toggle GPIO 3
        gpioWrite(GPIO_3, (i + 1) % 2);
        printf("GPIO %d set to %d\n", GPIO_3, (i + 1) % 2);

        // Wait for 1 second
        result = sleep(1);
        if (result != 0) {
            perror("sleep");
            break; // Exit loop if sleep fails
        }
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
