#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = 0; // 0: LOW, 1: HIGH

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("GPIO %d control program started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Set the GPIO pin to the current state
        gpioWrite(GPIO_PIN, current_state);

        // Print the current state
        printf("GPIO %d is now %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");

        // Toggle the state
        current_state = !current_state;

        // Wait for 60 seconds
        sleep(60);
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

