}

int main() {
    int current_state = 0; // 0: LOW, 1: HIGH
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
