    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Set the GPIO pin to the current state
        result = gpioWrite(GPIO_PIN, current_state);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_PIN, result);
        } else {
            printf("GPIO %d set to %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");
        }

        // Toggle the state
        current_state = !current_state;

        // Wait for 5 seconds
        sleep(5);
