#define W1_SLAVE_FILE "w1_slave"
#define MAX_SENSOR_ID_LENGTH 20

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
char sensor_ids[MAX_SENSORS][MAX_SENSOR_ID_LENGTH];
int num_sensors = 0;

