// Function to discover DS18B20 sensors
int discover_sensors(char sensor_ids[][MAX_SENSOR_ID_LENGTH], int max_sensors, int max_id_length) {
    DIR *dir;
    struct dirent *entry;
    int count = 0;

    dir = opendir(W1_DEVICES_PATH);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_PATH);
        return -1;
    }

    while ((entry = readdir(dir)) != NULL && count < max_sensors) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[count], entry->d_name, max_id_length - 1);
            sensor_ids[count][max_id_length - 1] = '\0'; // Ensure null termination
            count++;
        }
    }

    closedir(dir);
    return count;
}

// Function to read temperature from a DS18B20 sensor
float read_temperature(const char *sensor_id) {
    char path[256];
    char line[256];
    int fd;
    ssize_t bytes_read;
    float temperature = -999.0; // Default error value

    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_PATH, sensor_id, W1_SLAVE_FILE);

    fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening " W1_SLAVE_FILE);
        return -999.0;
    }

    // Read the file twice to get a valid temperature reading
    bytes_read = read(fd, line, sizeof(line));
    if (bytes_read == -1) {
        perror("Error reading " W1_SLAVE_FILE);
        close(fd);
        return -999.0;
    }
    lseek(fd, 0, SEEK_SET); // Reset file pointer to the beginning
    bytes_read = read(fd, line, sizeof(line));
    if (bytes_read == -1) {
        perror("Error reading " W1_SLAVE_FILE);
        close(fd);
        return -999.0;
    }

    close(fd);

    // Parse the temperature from the file content
    char *temp_str = strstr(line, "t=");
    if (temp_str != NULL) {
        long temp_reading = strtol(temp_str + 2, NULL, 10);
        temperature = (float)temp_reading / 1000.0;
    } else {
        fprintf(stderr, "Error: Temperature data not found in %s\n", path);
        return -999.0;
    }

    return temperature;
}

// Cleanup function to release resources
