}

int main() {
    int i;
    float temperature;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Discover DS18B20 sensors
    num_sensors = discover_sensors(sensor_ids, MAX_SENSORS, MAX_SENSOR_ID_LENGTH);
    if (num_sensors < 0) {
        fprintf(stderr, "Error discovering sensors. Exiting.\n");
        return 1;
    } else if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    printf("Found %d DS18B20 sensors:\n", num_sensors);
    for (i = 0; i < num_sensors; i++) {
        printf("  Sensor %d: %s\n", i + 1, sensor_ids[i]);
    }

    // Read temperature from each sensor 3 times, every 5 seconds
    for (i = 0; i < 3 && program_running; i++) {
        printf("\n--- Reading %d ---\n", i + 1);
        for (int j = 0; j < num_sensors; j++) {
            temperature = read_temperature(sensor_ids[j]);
            if (temperature != -999.0) {
                printf("  Sensor %s: %.2f °C\n", sensor_ids[j], temperature);
            } else {
                fprintf(stderr, "  Error reading temperature from sensor %s\n", sensor_ids[j]);
            }
        }
        sleep(5);
    }

    cleanup();
    return 0;
}

