        return -1;
    }

    if (gpiod_line_request_output(*line, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", pin);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line value to %d\n", value);
        return -1;
    }
    return 0;
}

