#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variables
static volatile int running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate pulse width
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (diff_tick / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 distance sensor program. Press Ctrl+C to exit.\n");

    // Main loop
    while (running)
    {
        float distance = measure_distance();

        if (distance >= 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        gpioDelay(100); // Wait 0.1 seconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

