int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(1);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    int timings[MAX_TIMINGS];
    int i = 0;

    for (i = 0; i < MAX_TIMINGS; i++) {
        int counter = 0;
        while (gpioRead(gpio) == laststate) {
            counter++;
            gpioDelay(1);
            if (counter == 255) {
                break;
            }
        }
        laststate = gpioRead(gpio);
        timings[i] = counter;
        if (counter == 255) break;
    }

    int bit_idx = 0;
    for (i = 0; i < 40; i++) {
        int idx = 2 * i + 1;
        if (timings[idx] > timings[idx + 1]) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    if (j < 40) {
        fprintf(stderr, "DHT22: Not enough data received\n");
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

