#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define timeout in microseconds
#define TIMEOUT 50000 // 50ms

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Structure to hold callback data
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} callback_data_t;

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user)
{
    callback_data_t *data = (callback_data_t *)user;
    data->gpio = gpio;
    data->level = level;
    data->tick = tick;

    if (level == 1) {
        pulse_start = tick;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
    }
}

// Function to generate a trigger pulse
void trigger_pulse()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback function for echo pin
    callback_data_t echo_data;
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &echo_data);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo pulse or timeout
        int start_time = gpioTick();
        while (pulse_width == 0 && (gpioTick() - start_time) < TIMEOUT) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Check for timeout
        if (pulse_width == 0) {
            timeout_flag = 1;
            printf("Timeout occurred\n");
            break; // Exit loop on timeout
        }

        // Calculate distance in centimeters
        float distance = pulse_width / 58.0;

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Small delay before next measurement
        gpioDelay(100000); // 100ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

