#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the BME280 sensor
int bme280_init(int fd) {
    // Set humidity oversampling to 1x
    if (i2c_smbus_write_byte_data(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        perror("Failed to write to CTRL_HUM register");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_smbus_write_byte_data(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        perror("Failed to write to CTRL_MEAS register");
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (i2c_smbus_write_byte_data(fd, BME280_REG_CONFIG, 0x00) < 0) {
        perror("Failed to write to CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read data from the BME280 sensor
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity) {
    uint8_t data[8];
    int32_t raw_temperature, raw_pressure, raw_humidity;

    // Read 8 bytes of data starting from pressure MSB
    if (i2c_smbus_read_i2c_block_data(fd, BME280_REG_PRESSURE_MSB, (char *)data, 8) != 8) {
        perror("Failed to read data from BME280");
        return -1;
    }

    // Combine the pressure data
    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

    // Combine the temperature data
    raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Combine the humidity data
    raw_humidity = (data[6] << 8) | data[7];

    // Dummy conversion (replace with actual BME280 conversion formulas)
    *temperature = (float)raw_temperature / 100.0;
    *pressure = (float)raw_pressure / 100.0;
    *humidity = (float)raw_humidity / 100.0;

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    float temperature, pressure, humidity;
    int retries = 3; // Number of retries for I2C initialization

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    while (retries > 0) {
        i2c_fd = open(i2c_device, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            retries--;
            sleep(1); // Wait before retrying
        } else {
            break; // I2C device opened successfully
        }
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device after multiple retries. Exiting.\n");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BME280 sensor
    if (bme280_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BME280 sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Read and print data 3 times, every 5 seconds
    for (int i = 0; i < 3 && !terminate; i++) {
        if (bme280_read_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            printf("Temperature: %.2f \u00b0C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read data from BME280 sensor.\n");
        }
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);
    i2c_fd = -1; // Reset file descriptor

    return 0;
}

