// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize the VEML7700
int veml7700_init(int fd);

// Function to read ALS data from the VEML7700
int veml7700_read_als(int fd, uint16_t *als_data);

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init(i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t als_data;

    // Main loop
    while (1) {
        // Read ALS data
        if (veml7700_read_als(i2c_fd, &als_data) == 0) {
            // Print ALS data
            printf("ALS: %u\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data.\n");
        }

        // Sleep for 0.5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the VEML7700
int veml7700_init(int fd) {
    // Set configuration register (example: gain 2, integration time 100ms)
    uint8_t config_data[2];
    config_data[0] = VEML7700_ALS_CONF;
    config_data[1] = 0x00; // ALS_EN, ALS_IT_100MS, ALS_GAIN_2X

    if (write(fd, config_data, 2) != 2) {
        perror("Error writing to configuration register");
        return -1;
    }

    return 0;
}

// Function to read ALS data from the VEML7700
int veml7700_read_als(int fd, uint16_t *als_data) {
    uint8_t reg_addr = VEML7700_ALS;
    uint8_t als_data_bytes[2];

    // Write the register address to be read
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    // Read the ALS data (2 bytes)
    if (read(fd, als_data_bytes, 2) != 2) {
        perror("Error reading ALS data");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    *als_data = (als_data_bytes[0] << 8) | als_data_bytes[1];

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your Raspberry Pi configuration
#define BAUD_RATE B9600
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout of TIMEOUT_MS milliseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd) {
    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);

    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred, no data available
            return 0;
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return bytes_read;
    } else {
        // No data read
        return 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd);
        if (bytes_read > 0) {
            printf("Received: %s", (char*)malloc(bytes_read + 1));
            ((char*)malloc(bytes_read + 1))[bytes_read] = '\0';
            printf("\n");
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        usleep(100000); // 0.1 seconds
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("UART communication stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout in microseconds

// Global variables
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
double measure_distance();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate pulse width
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioSetMode(TRIGGER_PIN, PI_INPUT); // Set trigger pin to input
    gpioSetMode(ECHO_PIN, PI_INPUT);    // Set echo pin to input
    gpioTerminate();                   // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to measure distance\n");
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

