#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins to be used
const int pins[] = {4, 17, 18, 22, 23, 24, 25, 27};
const int num_pins = sizeof(pins) / sizeof(pins[0]);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        gpioWrite(pins[i], 0); // Initialize all pins to LOW
    }
    return 0;
}

// Function to set the state of all GPIO pins
void set_gpio_states(int state) {
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], state);
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 0); // Set all pins to LOW before exiting
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to toggle the GPIO pins
    while (program_running) {
        set_gpio_states(1); // Set all pins HIGH
        printf("GPIOs set HIGH\n");
        gpioDelay(50000); // Wait 50ms

        set_gpio_states(0); // Set all pins LOW
        printf("GPIOs set LOW\n");
        gpioDelay(50000); // Wait 50ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line4, *line17, *line27;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close GPIO lines
    if (line4) {
        gpiod_line_release(line4);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    int value = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line4 || !line17 || !line27) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line4, "gpio4_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 4 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line17, "gpio17_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line27, "gpio27_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 4 to value
        ret = gpiod_line_set_value(line4, value);
        if (ret < 0) {
            perror("Error setting GPIO 4 value");
            break;
        }
        printf("GPIO 4: %d\n", value);

        // Set GPIO 17 to value
        ret = gpiod_line_set_value(line17, value);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        printf("GPIO 17: %d\n", value);

        // Set GPIO 27 to value
        ret = gpiod_line_set_value(line27, value);
        if (ret < 0) {
            perror("Error setting GPIO 27 value");
            break;
        }
        printf("GPIO 27: %d\n", value);

        // Toggle the value
        value = !value;

        // Wait for 0.5 seconds
        usleep(500000); // 500000 microseconds = 0.5 seconds
    }

    // Cleanup (in case the loop breaks due to an error)
    signal_handler(SIGINT);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 18 as output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    /* Set PWM range */
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("PWM control on GPIO %d. Press Ctrl+C to exit.\n", PWM_GPIO);

    /* Main loop */
    while (!terminate) {
        /* Set duty cycle to 0 */
        duty_cycle = 0;
        gpioPWM(PWM_GPIO, duty_cycle);
        printf("GPIO %d: 0\n", PWM_GPIO);
        gpioDelay(100000); // 0.1 seconds

        /* Set duty cycle to 1000 */
        duty_cycle = PWM_RANGE;
        gpioPWM(PWM_GPIO, duty_cycle);
        printf("GPIO %d: 1000\n", PWM_GPIO);
        gpioDelay(100000); // 0.1 seconds
    }

    /* Clean up and terminate */
    gpioPWM(PWM_GPIO, 0); // Set duty cycle to 0 before exiting
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

