#define TIMEOUT 100000        // us (100ms)

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Handle timer wrap-around
        }
    }
}

// Calculate distance function
double calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

