    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo or timeout
        int start_time = gpioTick();
        while (pulse_width == 0 && (gpioTick() - start_time) < TIMEOUT) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Check for timeout
        if (pulse_width == 0) {
            timeout_flag = 1;
            printf("Timeout occurred\n");
        } else {
            timeout_flag = 0;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Reset pulse width for next measurement
        pulse_width = 0;

        // Delay before next measurement
