// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize the TCS34725 sensor
int init_tcs34725(int fd) {
    // Enable power and ALS
    uint8_t enable_value = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = enable_value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to enable TCS34725");
        return -1;
    }

    return 0;
}

// Function to read data from the TCS34725 sensor
int read_tcs34725(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to TCS34725");
        return -1;
    }

    if (read(fd, buf, 8) != 8) {
        perror("Failed to read from TCS34725");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

