#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your Raspberry Pi configuration
#define BAUD_RATE B9600
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_serial_port(const char *port_name, speed_t baud_rate) {
    int fd = open(port_name, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    serial_fd = setup_serial_port(UART_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        fprintf(stderr, "Failed to setup serial port. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    time_t rawtime;
    struct tm *timeinfo;

    printf("Serial communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Received: %s", timestamp, buffer);
        } else if (bytes_read < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("Error reading from serial port");
                break;
            }
        }

        usleep(100000); // 0.1 seconds
    }

    if (serial_fd != -1) {
        close(serial_fd);
        printf("Serial port closed.\n");
    }

    return EXIT_SUCCESS;
}

