#define TIMEOUT 50000 // 50ms

// Global variables
static volatile int echo_start = 0;
static volatile int echo_end = 0;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start = 1;
            start_tick = tick;
        } else if (level == 0) {
            echo_end = 1;
            end_tick = tick;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Reset variables
        echo_start = 0;
        echo_end = 0;
        start_tick = 0;
        end_tick = 0;
        timeout_flag = 0;

        // Wait for echo or timeout
        unsigned int start_time = gpioTick();
        while (!echo_end && !timeout_flag) {
            if (gpioTick() - start_time > TIMEOUT) {
                timeout_flag = 1;
                break;
            }
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Calculate pulse width and distance
        if (echo_end && !timeout_flag) {
            unsigned int pulse_width = end_tick - start_tick;
            float distance = pulse_width / 58.0; // Speed of sound: 343 m/s

            // Print results
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Timeout or error\n");
        }

        // Exit after one measurement
        break;
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

