// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to read a 16-bit value from the MPU6050
int16_t read_mpu6050_data(int reg)
{
    uint8_t buffer[2];
    int result;

    // Write the register address to be read
    result = write(i2c_fd, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }

    // Read two bytes from the register
    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }

    // Combine the two bytes into a 16-bit value
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

int main()
{
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

