        int16_t accel_x = read_mpu6050_data(MPU6050_ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_data(MPU6050_ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6050_data(MPU6050_ACCEL_XOUT_H + 4);

