static volatile int keepGoing = 1 ;

static void signalHandler (int sig)
{
  keepGoing = 0 ;
  (void)sig ;
}

int main (void)
{
  struct gpiod_chip *chip ;
  struct gpiod_line *line ;
  int value = 0 ;

  signal (SIGINT, signalHandler) ;

  printf ("Raspberry Pi wiringPi GPIO blink\n") ;
  printf ("===============================\n") ;
  printf ("\n") ;
  printf ("Connect a LED (and resistor) to GPIO %d and watch it blink!\n", pin) ;
  printf ("\n") ;

  chip = gpiod_chip_open_by_name ("/dev/gpiomem") ;
  if (!chip)
  {
    fprintf (stderr, "Unable to open GPIO device: %m\n") ;
    exit (1) ;
  }

  line = gpiod_chip_get_line (chip, pin) ;
  if (!line)
  {
    fprintf (stderr, "Unable to get line %d: %m\n", pin) ;
    gpiod_chip_close (chip) ;
    exit (1) ;
  }

  if (gpiod_line_request_output (line, "blink", value, 0) < 0)
  {
    fprintf (stderr, "Unable to request line as an output: %m\n") ;
    gpiod_chip_close (chip) ;
    exit (1) ;
  }

  for (;;)
  {
    value ^= 1 ;
    if (gpiod_line_set_value (line, value) < 0)
    {
      fprintf (stderr, "Unable to set line value: %m\n") ;
      break ;
    }
    printf ("GPIO %d is now %s\n", pin, value ? "HIGH" : "LOW") ;
    usleep (600000) ;
  }

  gpiod_line_release (line) ;
  gpiod_chip_close (chip) ;

  return 0 ;
}
